SELECT*FROM SYS.sysdatabases WHERE NAME='BD_CLINICA'

CREATE DATABASE BD_CLINICA
ON 
PRIMARY (NAME=BD_CLINICA_DATA,
FILENAME='C:\CLINICA\CLINICA.MDF',
SIZE=5MB,
MAXSIZE=60MB,
FILEGROWTH=4MB)
LOG ON (NAME=BD_CLINICA_LOG,
FILENAME='C:\CLINICA\CLINICA.LDF',
SIZE=2MB,
MAXSIZE=40MB,
FILEGROWTH=1MB)
GO

USE BD_CLINICA

--********************************

CREATE TABLE SEGURO
(TIPOSEGURO CHAR(5) NOT NULL,
NOMBRESEGURO VARCHAR(25) NOT NULL,
PRIMARY KEY (TIPOSEGURO))

ALTER TABLE SEGURO
ADD  DESCT DECIMAL(10,2) NOT NULL

SELECT*FROM SEGURO

--*******************************

CREATE TABLE ADMI(
IDADMI CHAR(5) NOT NULL,
NOMBRE_ADMI VARCHAR(50) NOT NULL,
APELLIDO_ADMI VARCHAR(50) NOT NULL,
PRIMARY KEY(IDADMI))

ALTER TABLE ADMI
ADD DNI CHAR (8) NOT NULL,
TELEFO CHAR(9)NOT NULL,
FECREGIS DATE,
HORAREGIS TIME

SELECT*FROM ADMI

--*******************************************


CREATE TABLE PACIENTE(
IDPACIENTE CHAR(10) NOT NULL,
NOMBRE VARCHAR(25)NOT NULL,
APELLIDOS VARCHAR(25)NOT NULL,
DNI CHAR(8) NOT NULL,
TELF VARCHAR(9)NOT NULL,
CORREO VARCHAR(25)NOT NULL,
DIREC VARCHAR(50)NOT NULL,
FECNAC DATE NOT NULL,
EDAD INT NOT NULL,
TIPOSEGURO CHAR(5) NOT NULL,
FECREGIS DATE,
HORAREGIS TIME,
IDADMI CHAR(5) NOT NULL,
PRIMARY KEY (IDPACIENTE))
GO

ALTER TABLE PACIENTE 
ADD FOREIGN KEY (IDADMI) REFERENCES ADMI (IDADMI)

ALTER TABLE PACIENTE
ADD FOREIGN KEY (TIPOSEGURO) REFERENCES SEGURO (TIPOSEGURO)


SELECT*FROM PACIENTE

--************************************+

CREATE TABLE USUARIO(
IDPACIENTE CHAR(10) NOT NULL,
DNI CHAR(8) NOT NULL,
NOM_USUARIO VARCHAR(50) NOT NULL,
CORREO VARCHAR(25) NOT NULL,
CONTRASEÑA VARCHAR(25) NOT NULL)

ALTER TABLE USUARIO
ADD FOREIGN KEY(IDPACIENTE) REFERENCES PACIENTE (IDPACIENTE)

SELECT*FROM USUARIO

--*****************************************+

CREATE TABLE ESPECIALIDADES(
IDESPECI CHAR(10)NOT NULL,
NOM_ESPECI VARCHAR(20) NOT NULL,
DESCRIPCION VARCHAR(MAX)NULL,
PRIMARY KEY (IDESPECI))
GO

SELECT * FROM ESPECIALIDADES

--****************************************+

CREATE TABLE MEDICO(
IDMEDICO CHAR(10)NOT NULL,
NOM_MEDICO VARCHAR(25)NOT NULL,
APE_MEDICO VARCHAR(25)NOT NULL,
CMP CHAR(10) NOT NULL,
TELEFONO VARCHAR(9) NOT NULL,
CORREO VARCHAR(25)NOT NULL,
PRIMARY KEY (IDMEDICO))
GO

ALTER TABLE MEDICO
ADD IDESPECI CHAR(10) NOT NULL,
FECREGIS DATE,
HORAREGIS TIME

ALTER TABLE MEDICO
ADD FOREIGN KEY (IDESPECI) REFERENCES ESPECIALIDADES(IDESPECI)

SELECT * FROM MEDICO

--********************************************************+

CREATE TABLE CITA(
IDCITA CHAR(5)NOT NULL,
FECHA DATE NOT NULL,
HORA TIME NOT NULL,
ESTADO VARCHAR(10) NOT NULL,
OBSER VARCHAR (50) NULL,
IDPACIENTE CHAR(10) NOT NULL,
IDMEDICO CHAR(10) NOT NULL,
FECREGIS DATE,
HORAREGIS TIME,
PRIMARY KEY (IDCITA))
GO

ALTER TABLE CITA
ADD FOREIGN KEY (IDPACIENTE) REFERENCES PACIENTE(IDPACIENTE)

ALTER TABLE CITA
ADD FOREIGN KEY (IDMEDICO) REFERENCES MEDICO(IDMEDICO)

SELECT*FROM CITA

--***********************************************

CREATE TABLE ATENCIOCITA(
IDATENCITA CHAR(5) NOT NULL,
IDCITA CHAR(5) NOT NULL,
ESTADO VARCHAR (10) NOT NULL,
FECHA DATE NOT NULL,
HORA TIME NOT NULL,
INFO VARCHAR(50) NOT NULL,
FOREIGN KEY (IDCITA) REFERENCES CITA (IDCITA))

SELECT*FROM ATENCIOCITA

--***************************************************

CREATE TABLE PAGO(
IDPAGO CHAR(5)NOT NULL,
MONTO MONEY NOT NULL,
PAGO_FINAL MONEY NOT NULL,
FECHAPAGO DATE NOT NULL,
METODOPAGO VARCHAR(20)NOT NULL,
ESTADOPAGO VARCHAR(20)NOT NULL,
IDCITA CHAR(5) NOT NULL,
FECREGIS DATE,
HORAREGIS TIME,
PRIMARY KEY (IDPAGO))
GO

ALTER TABLE PAGO
ADD FOREIGN KEY (IDCITA) REFERENCES CITA (IDCITA)
GO

SELECT*FROM PAGO

--*************************************************

CREATE TABLE RECLAMO(
IDRECLAMO CHAR(10) NOT NULL,
DESCRIP VARCHAR(50) NOT NULL,
FECSOLUCION DATE NOT NULL,
ESTADORECLAMO VARCHAR(50) NOT NULL,
IDPACIENTE CHAR(10) NOT NULL,
FECREGIS DATE,
HORAREGIS TIME,
PRIMARY KEY (IDRECLAMO))
GO

ALTER TABLE RECLAMO
ADD FOREIGN KEY (IDPACIENTE) REFERENCES PACIENTE(IDPACIENTE)
GO

SELECT*FROM RECLAMO

--**************************************************+

CREATE TABLE RECETA(
IDRECETA CHAR(5) NOT NULL,
IDPACIENTE CHAR(10) NOT NULL,
IDMEDICO CHAR(10) NOT NULL,
CANTIDAD INT NOT NULL,
NOMMEDICAM VARCHAR(25)NOT NULL,
GRAMOSPASTILLA DECIMAL (10,0) NOT NULL,
DIAPASTILLA INT NOT NULL,
FECREGIS DATE,
HORAREGIS TIME,
PRIMARY KEY (IDRECETA),
FOREIGN KEY (IDPACIENTE) REFERENCES PACIENTE (IDPACIENTE),
FOREIGN KEY (IDMEDICO) REFERENCES MEDICO (IDMEDICO))

ALTER TABLE RECETA
ADD IDCITA CHAR(5) NOT NULL
FOREIGN KEY (IDCITA) REFERENCES CITA (IDCITA) 

ALTER TABLE RECETA 
ADD HORAPORTOMAR CHAR(5) NOT NULL

SELECT*FROM RECETA

--**************************************************+

CREATE TABLE FARMACIA(
IDMEDICAMENTO CHAR(5) NOT NULL,
NOMMEDICAM VARCHAR(25) NOT NULL,
GRAMOSPASTILLA  DECIMAL (10,0) NOT NULL,
PRECIOUNIDAD DECIMAL(10,0) NOT NULL,
PRIMARY KEY (IDMEDICAMENTO))

SELECT*FROM FARMACIA

--******************************************************

CREATE TABLE FARMACEUTICA(
IDFARMACEU CHAR(5) NOT NULL,
NOMBREF VARCHAR(25) NOT NULL,
APELLF VARCHAR(25) NOT NULL,
DNI CHAR(8) NOT NULL,
TELEF CHAR(9) NOT NULL,
FECREGIS DATE,
HORAREGIS TIME,
PRIMARY KEY (IDFARMACEU))

SELECT*FROM FARMACEUTICA

--***************************************+*********

CREATE TABLE ATENCRECETA(
IDATENCRECETA CHAR(5) NOT NULL,
IDRECETA CHAR(5) NOT NULL,
CANTIDAD INT NOT NULL,
IDMEDICAMENTO CHAR(5) NOT NULL,
PRECIOUNIDAD DECIMAL(10,0) NOT NULL,
PRECIOFARMA DECIMAL(10,0) NOT NULL,
SUMATOTALDELPAGO DECIMAL(10,0) NOT NULL,
IDFARMACEU CHAR(5) NOT NULL,
FECREGIS DATE,
HORAREGIS TIME,
PRIMARY KEY (IDATENCRECETA),
FOREIGN KEY (IDRECETA) REFERENCES RECETA (IDRECETA),
FOREIGN KEY (IDMEDICAMENTO) REFERENCES FARMACIA (IDMEDICAMENTO),
FOREIGN KEY (IDFARMACEU) REFERENCES FARMACEUTICA (IDFARMACEU))

ALTER TABLE ATENCRECETA
ADD IDDETALLE CHAR(5)  NOT NULL

ALTER TABLE ATENCRECETA
ADD IDPACIENTE CHAR(10) NOT NULL,
FOREIGN KEY (IDPACIENTE) REFERENCES PACIENTE (IDPACIENTE)

SELECT*FROM ATENCRECETA

--***************************************************

CREATE TABLE PAGOFARMA(
IDPAGOFARMA CHAR(5) NOT NULL,
IDATENCRECETA CHAR(5) NOT NULL,
IDDETALLE CHAR(5) NOT NULL,
IDPACIENTE CHAR(10) NOT NULL,
METOPAGO VARCHAR(20) NOT NULL,
SUMATOTALDELPAGO DECIMAL(10,0) NOT NULL,
IDFARMACEU CHAR(5) NOT NULL,
FECREGIS DATE,
HORAREGIS TIME,
PRIMARY KEY(IDPAGOFARMA),
FOREIGN KEY (IDPACIENTE) REFERENCES PACIENTE (IDPACIENTE),
FOREIGN KEY (IDFARMACEU) REFERENCES FARMACEUTICA (IDFARMACEU))

SELECT*FROM PAGOFARMA

--******************************************************

