-- 3) ¿QUIERO SABER CUANTAS PERSONAS PAGARON MINIMO Y MAXIMO PRECIO?
BEGIN
DECLARE @MAX_PAG DECIMAL, @MIN_PAG DECIMAL, @CANT_MIN INT, @CANT_MAX INT 
SELECT @MIN_PAG=MIN(MONTO) FROM PAGO 
SELECT @MAX_PAG=MAX(MONTO) FROM PAGO
SELECT @CANT_MIN=COUNT(*) FROM PAGO WHERE MONTO=@MIN_PAG
SELECT @CANT_MAX=COUNT(*) FROM PAGO WHERE MONTO=@MAX_PAG
PRINT 'LA CANTIDAD DEL MINIMO VALOR SON:'+STR(@CANT_MIN)
PRINT 'EL PAGO MINIMO ES:'+STR(@MIN_PAG)
PRINT 'LA CANTIDAD DEL MAXIMO VALOR SON:'+STR(@CANT_MAX)
PRINT 'EL PAGO MAXIMO ES:'+STR(@MAX_PAG)
END


-- 4) ¿PUEDES HACER UNA TABLA SIN AFECTAR UNA TABLA CREADA E INSERTAR DATOS?
CREATE PROCEDURE SP_INSERTAR_PACIENTE
@IDPACIENTE CHAR(10),
@NOMBRE VARCHAR(25),
@APELLIDOS VARCHAR(25),
@DNI CHAR(8),
@TELF VARCHAR(9),
@CORREO VARCHAR(25),
@DIREC VARCHAR(50),
@FECNAC DATE,
@TIPOSEGURO CHAR(5),
@IDADMI CHAR(5)
AS
BEGIN
    DECLARE @EDAD INT
    SET @EDAD = DATEDIFF(YEAR, @FECNAC, GETDATE())
    INSERT INTO PACIENTE(IDPACIENTE, NOMBRE, APELLIDOS, DNI, TELF, CORREO, DIREC,
    FECNAC, EDAD, TIPOSEGURO, FECREGIS, HORAREGIS, IDADMI)
    VALUES(@IDPACIENTE, @NOMBRE, @APELLIDOS, @DNI, @TELF, @CORREO, @DIREC,
    @FECNAC, @EDAD, @TIPOSEGURO, CAST(GETDATE() AS DATE), CAST(GETDATE() AS TIME), @IDADMI)
END
GO
