-- UPDATE
CREATE TRIGGER TR_UPDATE_PAGO
ON PAGO
AFTER UPDATE
AS
BEGIN
    IF EXISTS (SELECT 1 FROM inserted WHERE MONTO <= 0)
    BEGIN
        PRINT 'ERROR: El monto debe ser mayor a 0.'
        ROLLBACK TRANSACTION
    END
END
