--DELETE
CREATE TABLE HISTORIAL_RECLAMO(
IDRECLAMO CHAR(10),
DESCRIP VARCHAR(50),
ESTADORECLAMO VARCHAR(50),
IDPACIENTE CHAR(10),
FECHA_ELIMINADO DATE)
GO

CREATE TRIGGER TR_DELETE_RECLAMO
ON RECLAMO
AFTER DELETE
AS
BEGIN
    INSERT INTO HISTORIAL_RECLAMO(IDRECLAMO, DESCRIP, ESTADORECLAMO, IDPACIENTE, FECHA_ELIMINADO)
    SELECT IDRECLAMO, DESCRIP, ESTADORECLAMO, IDPACIENTE, GETDATE()
    FROM deleted
END
GO

SELECT * FROM RECLAMO
DELETE FROM RECLAMO WHERE IDRECLAMO = 'R015'

SELECT * FROM HISTORIAL_RECLAMO

-- INSERT, UPDATE Y DELETE
CREATE TRIGGER TR_PACIENTE
ON PACIENTE
AFTER INSERT, UPDATE, DELETE
AS
BEGIN
    -- INSERT: hay filas en inserted y ninguna en deleted
    IF EXISTS (SELECT 1 FROM inserted) AND NOT EXISTS (SELECT 1 FROM deleted)
    BEGIN
        INSERT INTO AUDITORIA_PACIENTE(IDPACIENTE, NOMBRE, APELLIDOS, ACCION, FECHA, HORA, USUARIO)
        SELECT IDPACIENTE, NOMBRE, APELLIDOS, 'INSERT',
               CAST(GETDATE() AS DATE), CAST(GETDATE() AS TIME), SUSER_SNAME()
        FROM inserted
    END

    -- UPDATE: hay filas en inserted y en deleted
    IF EXISTS (SELECT 1 FROM inserted) AND EXISTS (SELECT 1 FROM deleted)
    BEGIN
        INSERT INTO AUDITORIA_PACIENTE(IDPACIENTE, NOMBRE, APELLIDOS, ACCION, FECHA, HORA, USUARIO)
        SELECT IDPACIENTE, NOMBRE, APELLIDOS, 'UPDATE',
               CAST(GETDATE() AS DATE), CAST(GETDATE() AS TIME), SUSER_SNAME()
        FROM inserted
    END

    -- DELETE: hay filas en deleted y ninguna en inserted
    IF EXISTS (SELECT 1 FROM deleted) AND NOT EXISTS (SELECT 1 FROM inserted)
    BEGIN
        INSERT INTO AUDITORIA_PACIENTE(IDPACIENTE, NOMBRE, APELLIDOS, ACCION, FECHA, HORA, USUARIO)
        SELECT IDPACIENTE, NOMBRE, APELLIDOS, 'DELETE',
               CAST(GETDATE() AS DATE), CAST(GETDATE() AS TIME), SUSER_SNAME()
        FROM deleted
    END
END
GO

